//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex, MutexGuard};

pub type PlayerId = u32;

#[derive(Default)]
struct State {
    scores: HashMap<PlayerId, i64>,
    total: i64,
}

/// Clones share the same scores, so each match thread keeps its own handle.
///
/// One lock guards scores and total together: the old per-player locks were
/// taken in caller order (transfer A->B vs B->A deadlocked, A->A self-locked)
/// and award did read-then-write in separate critical sections (lost updates).
#[derive(Clone, Default)]
pub struct Board {
    state: Arc<Mutex<State>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    // Recover from poison: an unknown-id panic must not kill every other match thread.
    fn lock(&self) -> MutexGuard<'_, State> {
        self.state.lock().unwrap_or_else(|e| e.into_inner())
    }

    /// Re-joining an existing id replaces its score; the total follows.
    pub fn join(&self, id: PlayerId, score: i64) {
        let mut s = self.lock();
        let old = s.scores.insert(id, score).unwrap_or(0);
        s.total += score - old;
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let mut s = self.lock();
        let Some(score) = s.scores.get_mut(&id) else {
            drop(s);
            panic!("award: unknown player {id}, expected a joined PlayerId");
        };
        *score += points;
        s.total += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        let mut s = self.lock();
        for id in [from, to] {
            if !s.scores.contains_key(&id) {
                drop(s);
                panic!("transfer: unknown player {id}, expected a joined PlayerId");
            }
        }
        if from == to {
            return;
        }
        *s.scores.get_mut(&from).unwrap() -= points;
        *s.scores.get_mut(&to).unwrap() += points;
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        match self.lock().scores.get(&id) {
            Some(v) => *v,
            None => panic!("score: unknown player {id}, expected a joined PlayerId"),
        }
    }

    pub fn total(&self) -> i64 {
        self.lock().total
    }
}


